/* ============================================================
   CYBER VIOLET DARK THEME — OPTIMIZED OPACITIES
   Different transparency levels for different UI layers
   ============================================================ */

/* ===== BACKGROUND ===== */
html, body {
  background-color: transparent !important;
}

body {
  background-image: url('data:image/png;base64,') !important;
  background-size: cover !important;
  background-attachment: fixed !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
}

/* Main containers - transparent to show background */
.application,
.app-wrapper,
#opensearch-dashboards-body,
.euiPage,
.euiPageBody {
  background-color: transparent !important;
}

/* ===== LAYER 1: MOST TRANSPARENT (Background elements) ===== */
/* Dashboard panels - Very transparent for normal state */
.dshLayout--viewing .dshLayout__panel,
.react-grid-item:not(.react-grid-item--dragging),
.euiPanel,
.embPanel {
  background: rgba(20, 20, 40, 0.25) !important; /* Increased from 0.15 */
  backdrop-filter: blur(16px) !important;
  -webkit-backdrop-filter: blur(16px) !important;
  border: 1px solid rgba(122, 79, 255, 0.25) !important;
  border-radius: 10px !important;
  box-shadow: 0 4px 24px rgba(122, 79, 255, 0.12) !important;
}

/* ===== LAYER 2: MEDIUM TRANSPARENCY (Interactive elements) ===== */
/* Panel headers */
.dshPanel__header,
.embPanel__header {
  background: rgba(0, 0, 0, 0.3) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  border-bottom: 1px solid rgba(122, 79, 255, 0.3) !important;
}

/* Selected/Active panels */
.react-grid-item--selected .embPanel,
.embPanel--selected {
  background: rgba(31, 31, 58, 0.5) !important;
  backdrop-filter: blur(20px) !important;
  -webkit-backdrop-filter: blur(20px) !important;
  border: 2px solid #7a4fff !important;
  box-shadow: 0 0 20px rgba(122, 79, 255, 0.4) !important;
}

/* Dragging panels */
.react-grid-item--dragging,
.react-grid-item--resizing {
  opacity: 0.9 !important;
  background: rgba(31, 31, 58, 0.7) !important;
  backdrop-filter: blur(24px) !important;
  -webkit-backdrop-filter: blur(24px) !important;
  box-shadow: 0 8px 32px rgba(122, 79, 255, 0.3) !important;
}

/* ===== LAYER 3: HIGH OPACITY (Content panels that need clarity) ===== */
/* Tables and data grids - Higher opacity for readability */
.euiTable,
.euiBasicTable {
  background: rgba(2, 2, 4, 0.4) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
}

.euiTableRow td,
.euiTableRowCell {
  background: rgba(9, 9, 18, 0.35) !important;
  border-bottom-color: rgba(122, 79, 255, 0.2) !important;
  color: #e8e8ff !important;
}

.euiTableRow:hover td {
  background: rgba(31, 31, 58, 0.5) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
}

.euiTableHeaderCell,
.euiTableHeaderCell__button {
  background: rgba(6, 6, 12, 0.5) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  color: #7a4fff !important;
  border-bottom: 2px solid #7a4fff !important;
}

/* ===== LAYER 4: NEARLY OPAQUE (Modals, Flyouts, Popups) ===== */
/* Flyouts and modals - Much less transparent */
.euiFlyout,
.euiFlyoutBody,
.euiModal,
.euiModal__flex,
.euiPopover__panel,
.euiContextMenu {
  background: rgba(14, 14, 24, 0.85) !important; /* Much higher opacity */
  backdrop-filter: blur(20px) !important;
  -webkit-backdrop-filter: blur(20px) !important;
  border: 1px solid rgba(122, 79, 255, 0.3) !important;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4) !important;
}

/* Modal content */
.euiModal__header {
  background: rgba(122, 79, 255, 0.15) !important;
  border-bottom: 1px solid rgba(122, 79, 255, 0.3) !important;
}

.euiModal__footer {
  background: rgba(0, 0, 0, 0.3) !important;
  border-top: 1px solid rgba(122, 79, 255, 0.2) !important;
}

/* ===== LAYER 5: OPQAUE OVERLAYS (Loading, Error states) ===== */
/* Loading overlays */
.euiOverlayMask {
  background: rgba(0, 0, 0, 0.7) !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
}

/* ===== FORM ELEMENTS - Medium transparency ===== */
.euiFieldText,
.euiFieldSearch,
.euiFieldNumber,
.euiFieldPassword,
.euiSelect,
.euiTextArea,
.euiComboBox__inputWrap,
.euiSuperSelectControl {
  background: rgba(26, 26, 46, 0.5) !important;
  backdrop-filter: blur(10px) !important;
  -webkit-backdrop-filter: blur(10px) !important;
  border-color: rgba(122, 79, 255, 0.4) !important;
  color: #e8e8ff !important;
}

.euiFieldText:focus,
.euiFieldSearch:focus,
.euiComboBox__inputWrap--isFocused {
  border-color: #dfd4fe !important;
  box-shadow: 0 0 0 1px #dfd4fe, 0 0 12px rgba(122, 79, 255, 0.5) !important;
  background: rgba(26, 26, 46, 0.7) !important;
}

/* ===== TOOLTIPS - Medium transparency ===== */
.euiToolTip {
  background: rgba(31, 31, 58, 0.75) !important;
  backdrop-filter: blur(16px) !important;
  -webkit-backdrop-filter: blur(16px) !important;
  border: 1px solid rgba(122, 79, 255, 0.3) !important;
  color: #e8e8ff !important;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3) !important;
}

/* ===== EMPTY STATES - Medium transparency ===== */
.euiEmptyPrompt {
  background: rgba(20, 20, 40, 0.5) !important;
  backdrop-filter: blur(16px) !important;
  -webkit-backdrop-filter: blur(16px) !important;
  border: 1px solid rgba(122, 79, 255, 0.3) !important;
  border-radius: 10px !important;
}

/* ===== CODE BLOCKS ===== */
.euiCodeBlock {
  background: rgba(0, 0, 0, 0.5) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
}

.euiCode {
  background: rgba(31, 31, 58, 0.4) !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
  color: #00e59b !important;
}

/* ===== BADGES ===== */
.euiBadge {
  background: rgba(31, 31, 58, 0.6) !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
  border-color: rgba(122, 79, 255, 0.3) !important;
  color: #e8e8ff !important;
}

.euiBadge--primary {
  background: rgba(122, 79, 255, 0.3) !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
  color: #a78bfa !important;
}

/* ===== HEADER - Medium transparency ===== */
.euiHeader,
.euiHeader--dark,
.headerGlobalNav,
#globalHeaderBars {
  background: rgba(0, 0, 0, 0.4) !important;
  backdrop-filter: blur(20px) !important;
  -webkit-backdrop-filter: blur(20px) !important;
  border-bottom: 1px solid rgba(122, 79, 255, 0.3) !important;
  box-shadow: 0 1px 16px rgba(122, 79, 255, 0.2) !important;
}

/* ===== SIDEBAR - Medium transparency ===== */
.euiCollapsibleNav,
.euiNavDrawer,
.context-nav-wrapper,
[class*="collapsibleNav"] {
  background: rgba(14, 14, 24, 0.3) !important;
  backdrop-filter: blur(20px) !important;
  -webkit-backdrop-filter: blur(20px) !important;
  border-right: 1px solid rgba(122, 79, 255, 0.25) !important;
}

/* ===== QUERY BARS ===== */
.euiSearchBar,
.globalQueryBar,
.osdQueryBar,
.euiFormControlLayout {
  background: rgba(20, 20, 40, 0.3) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
}

